nextflow_process {

    name "Test Process WHATSHAP_HAPLOTAG"
    script "../main.nf"
    process "WHATSHAP_HAPLOTAG"

    tag "modules"
    tag "modules_nfcore"
    tag "whatshap"
    tag "whatshap/haplotag"
    tag "samtools/faidx"
    tag "whatshap/phase"

    setup {
        run("SAMTOOLS_FAIDX") {
            script "../../../samtools/faidx/main.nf"
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome3.fasta', checkIfExists: true),
                    []
                ]
                input[1] = false
                """
            }
        }
        run("WHATSHAP_PHASE") {
            script "../../../whatshap/phase/main.nf"
            process {
                """
                input[0] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/NA03697B2_new.pbmm2.repeats.vcf.gz', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/vcf/NA03697B2_new.pbmm2.repeats.vcf.gz.csi', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam.bai', checkIfExists: true),
                    [],
                ]

                input[1] = Channel.of([
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome3.fasta', checkIfExists: true)
                ]).join(SAMTOOLS_FAIDX.out.fai)
                """
            }
        }
    }


    test("whatshap - haplotag - bam") {

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                ]).join(WHATSHAP_PHASE.out.vcf)
                .join(WHATSHAP_PHASE.out.tbi)
                .map { meta, vcf, tbi ->
                                [ meta,
                                vcf,
                                tbi,
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam.bai', checkIfExists: true),
                                ]
                            }

                input[1] = [
                    [ id:'test' ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome3.fasta', checkIfExists: true)
                ]

                input[2] = SAMTOOLS_FAIDX.out.fai

                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("whatshap - haplotag - bam - noreference") {

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                ]).join(WHATSHAP_PHASE.out.vcf)
                .join(WHATSHAP_PHASE.out.tbi)
                .map { meta, vcf, tbi ->
                                [ meta,
                                vcf,
                                tbi,
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam.bai', checkIfExists: true),
                                ]
                            }

                input[1] = [[:], []]

                input[2] = [[:], []]

                input[3] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("whatshap - haplotag - bam - outputtsv") {

        when {
            process {
                """
                input[0] = Channel.of([
                    [ id:'test' ], // meta map
                ]).join(WHATSHAP_PHASE.out.vcf)
                .join(WHATSHAP_PHASE.out.tbi)
                .map { meta, vcf, tbi ->
                                [ meta,
                                vcf,
                                tbi,
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam', checkIfExists: true),
                                file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/NA03697B2_downsampled.pbmm2.repeats.bam.bai', checkIfExists: true),
